package rs.unicredit.cbr.config;

import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;

import lombok.RequiredArgsConstructor;

@Configuration
@RequiredArgsConstructor
@ConditionalOnProperty(prefix = "customs.services.gl-fee-prepare-data", name = "enabled", havingValue = "true")
@ConditionalOnClass(name = "com.ibm.as400.access.AS400JDBCDriver")
public class GlFeePrepareDataConfig {

    private final GlFeePrepareDataProperties properties;

    @Bean(name = "glFeePrepareDataJdbcTemplate")
    public JdbcTemplate glFeePrepareDataJdbcTemplate() {
        DriverManagerDataSource dataSource = new DriverManagerDataSource();
        dataSource.setDriverClassName(properties.getDriverClassName());
        dataSource.setUrl(properties.getUrl());
        dataSource.setUsername(properties.getUsername());
        dataSource.setPassword(properties.getPassword());
        return new JdbcTemplate(dataSource);
    }
}

