package rs.unicredit.cbr.config;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;

import javax.sql.DataSource;

import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.jdbc.core.JdbcTemplate;

class JdbcTemplateConfigTest {

    private final DataSource primaryDataSource = mock(DataSource.class);

    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner()
            .withBean(DataSource.class, () -> primaryDataSource)
            .withUserConfiguration(JdbcTemplateConfig.class, SecondaryJdbcTemplateConfig.class);

    @Test
    void createsPrimaryJdbcTemplateWhenSecondaryJdbcTemplateExists() {
        contextRunner.run(context -> {
            JdbcTemplate primaryTemplate = context.getBean(JdbcTemplate.class);
            JdbcTemplate namedPrimaryTemplate = context.getBean("jdbcTemplate", JdbcTemplate.class);
            JdbcTemplate secondaryTemplate = context.getBean("glFeePrepareDataJdbcTemplate", JdbcTemplate.class);

            assertThat(primaryTemplate).isSameAs(namedPrimaryTemplate);
            assertThat(primaryTemplate.getDataSource()).isSameAs(primaryDataSource);
            assertThat(secondaryTemplate).isNotSameAs(primaryTemplate);
        });
    }

    static class SecondaryJdbcTemplateConfig {

        @Bean(name = "glFeePrepareDataJdbcTemplate")
        JdbcTemplate glFeePrepareDataJdbcTemplate() {
            return new JdbcTemplate(mock(DataSource.class));
        }
    }
}

