package rs.unicredit.cbr.service;

import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.config.GlFeePrepareDataProperties;
import rs.unicredit.cbr.dto.GlFeePrepareDataResponse;
import rs.unicredit.cbr.model.TransferDirection;

@Service
@RequiredArgsConstructor
@ConditionalOnBean(name = "glFeePrepareDataJdbcTemplate")
public class GlFeePrepareDataService {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeePrepareDataService.class);
    private static final String FETCH_SQL_OUT = """
            SELECT f.*
            FROM TABLE(BEGPL.GET_FEEACCOUNT_OUT(CAST(? AS CHAR(16)))) f
            """;
    private static final String FETCH_SQL_IN = """
            SELECT f.*
            FROM TABLE(BEGPL.GET_FEEACCOUNT_IN(CAST(? AS CHAR(16)))) f
            """;

    @Qualifier("glFeePrepareDataJdbcTemplate")
    private final JdbcTemplate jdbcTemplate;
    private final GlFeePrepareDataProperties properties;
    private final ObjectMapper objectMapper;

    public GlFeePrepareDataResponse fetchByInRef(String inRef) {
        return fetchByInRef(inRef, TransferDirection.OUT);
    }

    public GlFeePrepareDataResponse fetchByInRef(String inRef, TransferDirection direction) {
        if (!properties.isEnabled()) {
            throw new IllegalStateException("GL fee prepare data service is disabled");
        }
        String normalizedInRef = normalize(inRef);
        if (normalizedInRef == null) {
            throw new IllegalArgumentException("INREF is required");
        }
        if (normalizedInRef.length() > 16) {
            throw new IllegalArgumentException("INREF must have at most 16 characters: " + normalizedInRef);
        }
        TransferDirection resolvedDirection = resolveDirection(direction);
        String functionName = resolveFunctionName(resolvedDirection);
        String fetchSql = resolveFetchSql(resolvedDirection);
        long startedAt = System.currentTimeMillis();
        List<Map<String, Object>> rows;
        try {
            rows = jdbcTemplate.query(
                    connection -> {
                        PreparedStatement statement = connection.prepareStatement(fetchSql);
                        statement.setString(1, normalizedInRef);
                        statement.setQueryTimeout(Math.max(1, properties.getQueryTimeoutSeconds()));
                        return statement;
                    },
                    (ResultSet rs) -> {
                        List<Map<String, Object>> result = new ArrayList<>();
                        ResultSetMetaData metaData = rs.getMetaData();
                        int columnCount = metaData.getColumnCount();
                        while (rs.next()) {
                            Map<String, Object> row = new LinkedHashMap<>();
                            for (int index = 1; index <= columnCount; index++) {
                                row.put(metaData.getColumnLabel(index), rs.getObject(index));
                            }
                            result.add(row);
                        }
                        return result;
                    });
        } catch (DataAccessException ex) {
            SQLException sqlException = extractSqlException(ex);
            String sqlState = sqlException != null ? sqlException.getSQLState() : null;
            int errorCode = sqlException != null ? sqlException.getErrorCode() : 0;
            String message = sqlException != null && sqlException.getMessage() != null
                    ? sqlException.getMessage()
                    : ex.getMostSpecificCause() != null ? ex.getMostSpecificCause().getMessage() : ex.getMessage();
            LOG.error(
                    "AS400 {} failed inRef={} direction={} sqlState={} errorCode={} message={}",
                    functionName,
                    normalizedInRef,
                    resolvedDirection,
                    sqlState,
                    errorCode,
                    message,
                    ex);
            throw new ResponseStatusException(
                    HttpStatus.BAD_GATEWAY,
                    "AS400 %s failed for inRef=%s direction=%s sqlState=%s errorCode=%s message=%s"
                            .formatted(functionName, normalizedInRef, resolvedDirection, sqlState, errorCode, message));
        }
        long durationMs = System.currentTimeMillis() - startedAt;
        LOG.info(
                "AS400 {} success inRef={} direction={} rowCount={} durationMs={} rows={}",
                functionName,
                normalizedInRef,
                resolvedDirection,
                rows.size(),
                durationMs,
                toJson(rows));
