package rs.unicredit.cbr.config;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Component;
import rs.unicredit.cbr.exception.CurrentUserException;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Component("authz")
public class RoleChecker {

    private static final Logger log = LoggerFactory.getLogger(RoleChecker.class);

    private final RolesProperties rolesProperties;

    public RoleChecker(RolesProperties rolesProperties) {
        this.rolesProperties = rolesProperties;
    }
    
    public boolean hasAnyOf(Authentication auth, String... roleGroups) {
        if (auth == null || roleGroups == null) {
            return false;
        }

        if (auth.getAuthorities() == null || auth.getAuthorities().isEmpty()) {
            throw new CurrentUserException("Current user has no roles assigned.");
        }

        Set<String> allowedRoles = new HashSet<>();

        for (String roleGroup : roleGroups) {
            if (roleGroup == null) {
                continue;
            }
            for (String groupName : roleGroup.split(",")) {
                String trimmed = groupName.trim();
                if (trimmed.isEmpty()) {
                    continue;
                }

                List<String> roles = rolesProperties.getRolesFor(trimmed);
                if (roles != null) {
                    allowedRoles.addAll(roles);
                } else {
                    log.debug("No role mapping found for group '{}'", trimmed);
                }
            }
        }
       
        boolean hasRole = auth.getAuthorities().stream().anyMatch(a -> allowedRoles.contains(a.getAuthority()));
        log.info("Roles in config: {}, user authorities: {}, access granted: {}", allowedRoles, auth.getAuthorities(), hasRole);

        if (!hasRole) {
            throw new CurrentUserException("Current user lacks required roles: " + allowedRoles);
        }
        return true;
    }
}

