        if (txn == null) {
            LOG.warn("Skipping fee-status update because transaction was not found for requestId={}", requestId);
            return;
        }
        if (shouldPreserveExistingFeeStatus(txn)) {
            LOG.info(
                    "Preserving existing fee status for requestId={} txnId={} direction={} creditorSegment={} feeStatus={}",
                    requestId,
                    txn.getId(),
                    txn.getDirection(),
