package rs.unicredit.cbr.mq;

import java.time.LocalDateTime;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.jms.core.JmsTemplate;
import org.springframework.stereotype.Service;

import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.model.CbrTransactionResponse;
import rs.unicredit.cbr.model.MessageType;
import rs.unicredit.cbr.model.TransferDirection;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;
import rs.unicredit.cbr.repository.CbrTransactionResponseRepository;
import rs.unicredit.cbr.service.GlFeeEligibility;
import rs.unicredit.cbr.service.StageTransitionService;

@Service
@ConditionalOnBean(name = "mqJmsTemplate")
public class MqMessageService {

    private static final Logger LOG = LoggerFactory.getLogger(MqMessageService.class);
    private static final int RESPONSE_ERROR_MESSAGE_MAX_LENGTH = 1024;

    private final JmsTemplate jmsTemplate;
    private final ObjectProvider<JmsTemplate> gseJmsTemplateProvider;
    private final ObjectProvider<JmsTemplate> omJmsTemplateProvider;
    private final MqProperties properties;
    private final CbrTransactionRequestRepository requestRepository;
    private final CbrTransactionRepository transactionRepository;
    private final CbrTransactionResponseRepository responseRepository;
    private final StageTransitionService stageTransitionService;

    public MqMessageService(@Qualifier("mqJmsTemplate") JmsTemplate jmsTemplate,
                            @Qualifier("gseMqJmsTemplate") ObjectProvider<JmsTemplate> gseJmsTemplateProvider,
                            @Qualifier("omMqJmsTemplate") ObjectProvider<JmsTemplate> omJmsTemplateProvider,
                            MqProperties properties,
                            CbrTransactionRequestRepository requestRepository,
                            CbrTransactionRepository transactionRepository,
                            CbrTransactionResponseRepository responseRepository,
                            StageTransitionService stageTransitionService) {
        this.jmsTemplate = jmsTemplate;
        this.gseJmsTemplateProvider = gseJmsTemplateProvider;
        this.omJmsTemplateProvider = omJmsTemplateProvider;
        this.properties = properties;
        this.requestRepository = requestRepository;
        this.transactionRepository = transactionRepository;
        this.responseRepository = responseRepository;
        this.stageTransitionService = stageTransitionService;
    }

    public void sendExampleCustomerXml(String username, String lastName, String address) {
        String payload = buildExampleCustomerXml(username, lastName, address);
        LOG.info("Sending IBM MQ message to queue {}", properties.getQueue());
        jmsTemplate.convertAndSend(properties.getQueue(), payload);
    }

    public String buildExampleCustomerXml(String username, String lastName, String address) {
        return """
                <customer>
                    <username>%s</username>
                    <lastName>%s</lastName>
                    <address>%s</address>
                </customer>
                """.formatted(username, lastName, address);
    }

    public void sendSample() {
        sendExampleCustomerXml("example-user", "Example", "Example Street 123, Example City");
    }

    public void sendCbrRequestToSkipper(Long requestId) {
        if (requestId == null) {
            return;
        }
        try {
            CbrTransactionRequest request = requestRepository.findById(requestId)
                    .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
            String payload = request.getRawXml();
            String destination = properties.getOutboundQueue() != null
                    ? properties.getOutboundQueue()
                    : properties.getQueue();
            LOG.info("Sending CBR request id={} to Skipper queue {}", requestId, destination);
            String correlationId = resolveSkipperCorrelationId(request);
            jmsTemplate.send(destination, session -> {
                jakarta.jms.TextMessage message = session.createTextMessage(payload);
                message.setJMSCorrelationID(correlationId);
                return message;
            });
            stageTransitionService.transitionByRequestId(requestId, "S4", "Poruka poslata ka Skipper");
        } catch (Exception ex) {
            stageTransitionService.transitionErrorByRequestId(
                    requestId, "Greska pri slanju poruke ka Skipperu", ex.getMessage());
            throw new IllegalStateException("Failed to send request to Skipper for requestId=" + requestId, ex);
        }
    }

    public void sendCbrRequestToGse(Long requestId) {
        JmsTemplate gseTemplate = gseJmsTemplateProvider.getIfAvailable();
        if (gseTemplate == null) {
            throw new IllegalStateException("GSE MQ template is not configured.");
        }
        LOG.info(
                "Resolved GSE MQ template for requestId={} defaultQueue={}",
                requestId,
                gseTemplate.getDefaultDestinationName());
        sendCbrRequest(requestId, gseTemplate, "GSE");
    }

    public void sendCbrRequestToOm(Long requestId) {
        JmsTemplate omTemplate = omJmsTemplateProvider.getIfAvailable();
        if (omTemplate == null) {
            throw new IllegalStateException("OM MQ template is not configured.");
        }
        LOG.info(
                "Resolved OM MQ template for requestId={} defaultQueue={}",
                requestId,
                omTemplate.getDefaultDestinationName());
        sendCbrRequest(requestId, omTemplate, "OM");
    }

    private void sendCbrRequest(Long requestId, JmsTemplate targetTemplate, String target) {
        if (requestId == null) {
            return;
        }
        CbrTransactionResponse response = null;
        try {
            long startedAt = System.currentTimeMillis();
            CbrTransactionRequest request = requestRepository.findById(requestId)
                    .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
            response = responseRepository.findFirstByRequest_IdOrderByIdDesc(requestId)
                    .orElseThrow(() -> new IllegalStateException(
                            "Prepared response not found for requestId=" + requestId));

            String payload = response.getRawXml();
            if (payload == null || payload.isBlank()) {
                throw new IllegalStateException("Prepared response payload is empty for requestId=" + requestId);
            }

            String destination = targetTemplate.getDefaultDestinationName();
            String correlationId = resolveCorrelationId(request);
            LOG.info(
                    "Sending CBR response id={} for requestId={} to {} queue={} correlationId={} payloadSize={}",
                    response.getId(),
                    requestId,
                    target,
                    destination,
                    correlationId,
                    payload.length());
            sendToDestination(targetTemplate, destination, payload, requestId, correlationId);
            long elapsedMs = System.currentTimeMillis() - startedAt;
            LOG.info(
                    "Successfully sent CBR response id={} for requestId={} to {} in {} ms",
                    response.getId(),
                    requestId,
                    target,
                    elapsedMs);
            response.setStatus("S10");
            response.setErrorMessage(null);
            responseRepository.save(response);
            LOG.info(
                    "Persisted response success state for requestId={} responseId={} target={} responseStatus={}",
                    requestId,
                    response.getId(),
                    target,
                    response.getStatus());
            updateFeeStatusForSuccessfulS10(requestId);
            stageTransitionService.transitionByRequestId(
                    requestId, "S10", "Poruka poslata ka " + target + " preko MQ");
            LOG.info(
                    "Completed MQ success stage transition for requestId={} target={} responseId={}",
                    requestId,
                    target,
                    response.getId());
        } catch (Exception ex) {
            LOG.error("Failed to send CBR response for requestId={} target={}: {}", requestId, target, ex.getMessage(), ex);
            if (response != null) {
                String normalizedError = normalizeErrorMessage(ex.getMessage());
                response.setErrorMessage(normalizedError);
                if (response.getStatus() == null || response.getStatus().isBlank()) {
                    response.setStatus("S9");
                }
                responseRepository.save(response);
            }
            stageTransitionService.transitionErrorByRequestId(
                    requestId, "Greska pri slanju poruke ka " + target + " preko MQ", ex.getMessage());
            throw new IllegalStateException(
                    "Failed to send request to " + target + " for requestId=" + requestId, ex);
        }
    }

    private void sendToDestination(String destination, String payload, Long requestId) {
        sendToDestination(jmsTemplate, destination, payload, requestId, String.valueOf(requestId));
    }

    private void sendToDestination(
            JmsTemplate template,
            String destination,
            String payload,
            Long requestId,
            String correlationId) {
        LOG.info(
                "Invoking JMS send requestId={} destination={} correlationId={} payloadSize={}",
                requestId,
                destination,
                correlationId,
                payload != null ? payload.length() : 0);
        template.send(destination, session -> {
            jakarta.jms.TextMessage message = session.createTextMessage(payload);
            message.setJMSCorrelationID(correlationId);
            return message;
        });
        LOG.info(
                "JMS send returned requestId={} destination={} correlationId={}",
                requestId,
                destination,
                correlationId);
    }

    private void updateFeeStatusForSuccessfulS10(Long requestId) {
        if (requestId == null) {
            return;
        }
        CbrTransactionRequest request = requestRepository.findById(requestId).orElse(null);
        CbrTransaction txn = request == null
                ? null
                : transactionRepository.findWithRegulatoryDetailsByRequestId(request.getId()).orElse(null);
        if (txn == null) {
            LOG.warn("Skipping fee-status update because transaction was not found for requestId={}", requestId);
            return;
        }
        if (shouldPreserveExistingFeeStatus(txn)) {
            LOG.info(
                    "Preserving existing fee status for requestId={} txnId={} direction={} creditorSegment={} feeStatus={}",
                    requestId,
                    txn.getId(),
                    txn.getDirection(),
                    txn.getCreditorSegment(),
                    txn.getFeeStatus());
            return;
        }
        String feeStatus = GlFeeEligibility.isReadyCandidate(txn) ? "READY" : "SKIPPED";
        LocalDateTime feeReadyAt = "READY".equals(feeStatus) ? LocalDateTime.now() : null;
        int updated = transactionRepository.updateFeeStateByRequestId(requestId, feeStatus, feeReadyAt);
        LOG.info(
                "Updated fee state for requestId={} feeStatus={} feeReadyAt={} updatedRows={}",
                requestId,
                feeStatus,
                feeReadyAt,
                updated);
    }

    private boolean shouldPreserveExistingFeeStatus(CbrTransaction txn) {
        if (txn == null) {
            return false;
        }
        String currentFeeStatus = txn.getFeeStatus();
        return currentFeeStatus != null && !currentFeeStatus.trim().isEmpty();
    }

    private String resolveCorrelationId(CbrTransactionRequest request) {
        if (request != null && request.getCorrelationId() != null && !request.getCorrelationId().isBlank()) {
            return request.getCorrelationId().trim();
        }
        return String.valueOf(request != null ? request.getId() : null);
    }

    private String resolveSkipperCorrelationId(CbrTransactionRequest request) {
        return String.valueOf(request != null ? request.getId() : null);
    }

    private String normalizeErrorMessage(String errorMessage) {
        if (errorMessage == null) {
            return null;
        }
        String trimmed = errorMessage.trim();
        if (trimmed.length() <= RESPONSE_ERROR_MESSAGE_MAX_LENGTH) {
            return trimmed;
        }
        return trimmed.substring(0, RESPONSE_ERROR_MESSAGE_MAX_LENGTH);
    }
}

