@Component
public class CbrTransactionDtoMapper {

    public List<CbrTransactionDTO> toDtoList(
            List<CbrTransaction> transactions,
            Map<String, String> statusShortNamesByCode) {
        if (transactions == null || transactions.isEmpty()) {
            return List.of();
        }

        return transactions.stream()
                .map(transaction -> toListDto(transaction, statusShortNamesByCode))
                .toList();
    }

    public List<CbrTransactionDTO> toArchiveDtoList(
            List<CbrTransactionArchive> transactions,
            Map<String, String> statusShortNamesByCode) {
        if (transactions == null || transactions.isEmpty()) {
            return List.of();
        }

        return transactions.stream()
                .map(transaction -> toArchiveDto(transaction, statusShortNamesByCode))
                .toList();
    }

    public List<CbrTransactionDTO> toArchiveSearchDtoList(
            List<CbrTransactionArchive> transactions,
            Map<String, String> statusShortNamesByCode) {
        if (transactions == null || transactions.isEmpty()) {
            return List.of();
        }

        return transactions.stream()
                .map(transaction -> toArchiveSearchDto(transaction, statusShortNamesByCode))
                .toList();
    }

    public CbrTransactionDTO toDto(
            CbrTransaction transaction,
            Map<String, String> statusShortNamesByCode) {
        var dto = new CbrTransactionDTO();
        BeanUtils.copyProperties(transaction, dto, "regulatoryDetails");
        dto.setRegulatoryDetails(transaction != null ? transaction.getRegulatoryDetails() : List.of());
        populateRequestMetadata(dto, transaction != null ? transaction.getRequest() : null);
        applyStatusShortName(dto, transaction != null ? transaction.getStatus() : null, statusShortNamesByCode);
        return dto;
    }

    public CbrTransactionDTO toListDto(
            CbrTransaction transaction,
            Map<String, String> statusShortNamesByCode) {
        var dto = new CbrTransactionDTO();
        BeanUtils.copyProperties(transaction, dto, "regulatoryDetails", "request");
        dto.setRegulatoryDetails(List.of());
        applyStatusShortName(dto, transaction != null ? transaction.getStatus() : null, statusShortNamesByCode);
        return dto;
    }

    @SuppressWarnings("unchecked")
    public CbrTransactionDTO toArchiveDto(
            CbrTransactionArchive transaction,
            Map<String, String> statusShortNamesByCode) {
        var dto = new CbrTransactionDTO();
        BeanUtils.copyProperties(transaction, dto, "regulatoryDetails");
        dto.setRegulatoryDetails((List) (transaction != null ? transaction.getRegulatoryDetails() : List.of()));
        dto.setArchivedAt(transaction != null ? transaction.getArchivedAt() : null);
        populateRequestMetadata(dto, transaction != null ? transaction.getRequest() : null);
        applyStatusShortName(dto, transaction != null ? transaction.getStatus() : null, statusShortNamesByCode);
        return dto;
    }

    public CbrTransactionDTO toArchiveSearchDto(
            CbrTransactionArchive transaction,
            Map<String, String> statusShortNamesByCode) {
        var dto = new CbrTransactionDTO();
        BeanUtils.copyProperties(transaction, dto, "regulatoryDetails");
        dto.setRegulatoryDetails(List.of());
        dto.setArchivedAt(transaction != null ? transaction.getArchivedAt() : null);
        populateRequestMetadata(dto, transaction != null ? transaction.getRequest() : null);
        applyStatusShortName(dto, transaction != null ? transaction.getStatus() : null, statusShortNamesByCode);
        return dto;
    }

    private void populateRequestMetadata(CbrTransactionDTO dto, CbrTransactionRequest request) {
        if (dto == null || request == null) {
            return;
        }

        dto.setRequestId(request.getId());
        dto.setRequestErrorMessage(request.getErrorMessage());
        dto.setRequestSourceSystem(request.getSourceSystem());
        dto.setRequestCorrelationId(request.getCorrelationId());
    }

    private void applyStatusShortName(
            CbrTransactionDTO dto,
            String statusCode,
            Map<String, String> statusShortNamesByCode) {
        if (dto == null) {
            return;
        }

        if (statusCode == null || statusCode.isBlank()) {
            dto.setStatusShortName(null);
            return;
        }

        dto.setStatusShortName(statusShortNamesByCode.getOrDefault(statusCode, statusCode));
    }
}

