import jakarta.jms.ConnectionFactory;
import jakarta.jms.JMSException;
import java.net.InetSocketAddress;
import java.net.Socket;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jms.annotation.EnableJms;
import org.springframework.jms.config.DefaultJmsListenerContainerFactory;
import org.springframework.jms.connection.CachingConnectionFactory;
import org.springframework.jms.core.JmsTemplate;

@Configuration
@EnableJms
@EnableConfigurationProperties(MqProperties.class)
public class MqConfig {

    private static final Logger LOG = LoggerFactory.getLogger(MqConfig.class);

    @Bean
    @ConditionalOnProperty(prefix = "customs.mq", name = "enabled", havingValue = "true")
    public MQConnectionFactory ibmMqConnectionFactory(MqProperties properties) throws JMSException {
        if (properties.isConnectivityCheckEnabled() && properties.getHost() != null) {
            probeHostPort(properties.getHost(), properties.getPort(), properties.getConnectivityCheckTimeoutMs());
        }
        MQConnectionFactory factory = new MQConnectionFactory();
        factory.setTransportType(WMQConstants.WMQ_CM_CLIENT);
        factory.setHostName(properties.getHost());
        factory.setPort(properties.getPort());
        factory.setQueueManager(properties.getQueueManager());
        factory.setChannel(properties.getChannel());
        factory.setAppName(properties.getAppName());
        factory.setStringProperty(WMQConstants.USERID, properties.getUsername());
        factory.setStringProperty(WMQConstants.PASSWORD, properties.getPassword());
        factory.setBooleanProperty(WMQConstants.USER_AUTHENTICATION_MQCSP, true);
        if (properties.isUseTls() && properties.getCipherSuite() != null) {
            factory.setSSLCipherSuite(properties.getCipherSuite());
        }
        LOG.info("IBM MQ connection factory initialized for host {}:{} qm {}", properties.getHost(), properties.getPort(),
                properties.getQueueManager());
        return factory;
    }

    @Bean
    @ConditionalOnBean(name = "ibmMqConnectionFactory")
    @org.springframework.context.annotation.Primary
    public ConnectionFactory mqCachingConnectionFactory(
            @Qualifier("ibmMqConnectionFactory") MQConnectionFactory baseFactory) {
        CachingConnectionFactory cachingConnectionFactory = new CachingConnectionFactory(baseFactory);
        cachingConnectionFactory.setReconnectOnException(true);
        cachingConnectionFactory.setSessionCacheSize(5);
        return cachingConnectionFactory;
    }

    @Bean
    @ConditionalOnBean(name = "mqCachingConnectionFactory")
    public DefaultJmsListenerContainerFactory mqListenerContainerFactory(
            @Qualifier("mqCachingConnectionFactory") ConnectionFactory connectionFactory) {
        DefaultJmsListenerContainerFactory factory = new DefaultJmsListenerContainerFactory();
        factory.setConnectionFactory(connectionFactory);
        factory.setSessionTransacted(false);
        factory.setConcurrency("1-3");
        factory.setExceptionListener(ex -> LOG.error("MQ connection exception detected", ex));
        factory.setErrorHandler(t -> LOG.error("MQ listener error", t));
        return factory;
    }

    @Bean
    @ConditionalOnBean(name = "mqCachingConnectionFactory")
    public JmsTemplate mqJmsTemplate(
            @Qualifier("mqCachingConnectionFactory") ConnectionFactory connectionFactory,
            MqProperties properties) {
        JmsTemplate jmsTemplate = new JmsTemplate(connectionFactory);
        String defaultQueue = properties.getOutboundQueue() != null
                ? properties.getOutboundQueue()
                : properties.getQueue();
        if (defaultQueue != null) {
            jmsTemplate.setDefaultDestinationName(defaultQueue);
        }
        LOG.info("JMS template configured with default queue {}", defaultQueue);
        return jmsTemplate;
    }

    private void probeHostPort(String host, int port, int timeoutMs) {
        int effectiveTimeoutMs = timeoutMs > 0 ? timeoutMs : 2000;
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(host, port), effectiveTimeoutMs);
            LOG.info("MQ connectivity check OK to {}:{} ({} ms)", host, port, effectiveTimeoutMs);
        } catch (Exception ex) {
            LOG.warn("MQ connectivity check FAILED to {}:{} ({} ms): {}", host, port, effectiveTimeoutMs, ex.getMessage());
        }
    }
}

