                        + "deletedTransactions={}, deletedTransactionStats={}, deletedSnapshots={}",
                result.archivedTransactions(),
                result.archivedTransactionStats(),
                result.archivedSnapshots(),
                result.deletedTransactions(),
                result.deletedTransactionStats(),
                result.deletedSnapshots());
    }
}
