import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import lombok.RequiredArgsConstructor;

@Component
@RequiredArgsConstructor
@ConditionalOnProperty(prefix = "customs.fee-booking.archive", name = "enabled", havingValue = "true")
public class GlFeeDataArchiveScheduler {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeDataArchiveScheduler.class);

    private final GlFeeDataArchiveService glFeeDataArchiveService;

    @Scheduled(
            cron = "${customs.fee-booking.archive.cron:0 0 4 * * *}",
            zone = "${customs.fee-booking.archive.zone:Europe/Belgrade}")
    public void archiveDaily() {
        GlFeeDataArchiveService.ArchiveResult result = glFeeDataArchiveService.archiveBookedFeeData();
        LOG.info(
                "GL fee archive completed: archivedFeeRows={}, archivedBookingLogRows={}, deletedFeeRows={}, deletedBookingLogRows={}",
                result.archivedFeeRows(),
                result.archivedBookingLogRows(),
                result.deletedFeeRows(),
                result.deletedBookingLogRows());
    }
}

package rs.unicredit.cbr.service;

import java.time.LocalDateTime;
import java.util.concurrent.atomic.AtomicBoolean;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@ConditionalOnProperty(prefix = "customs.fee-booking.take-ready", name = "enabled", havingValue = "true")
public class GlFeeReadyTakeScheduler {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeReadyTakeScheduler.class);

    private final GlFeeDataService glFeeDataService;
    private final AtomicBoolean running = new AtomicBoolean(false);

    @Value("${customs.fee-booking.take-ready.ready-delay-minutes:10}")
    private int readyDelayMinutes;

    @Scheduled(fixedDelayString = "${customs.fee-booking.take-ready.fixed-delay-ms:60000}")
    public void takeReadyTransactions() {
        if (!running.compareAndSet(false, true)) {
            LOG.info("Skipping GL fee take scheduler because previous run is still in progress.");
            return;
        }
        try {
            int normalizedDelayMinutes = Math.max(0, readyDelayMinutes);
            LocalDateTime cutoff = LocalDateTime.now().minusMinutes(normalizedDelayMinutes);
            int taken = glFeeDataService.takeReadyTransactionsIntoFeeData(cutoff);
            LOG.info(
                    "GL fee take scheduler finished cutoff={} delayMinutes={} taken={}",
                    cutoff,
                    normalizedDelayMinutes,
                    taken);
        } catch (Exception ex) {
            LOG.error("GL fee take scheduler failed: {}", ex.getMessage(), ex);
        } finally {
            running.set(false);
        }
    }
}
