    @Column(name = "CALL_REPLY_REF", length = 70, nullable = false, unique = true)
    private String callReplyRef;

    @Column(name = "MESSAGE_TYPE", length = 10, nullable = false)
    private String messageType;

    @Column(name = "DIRECTION", length = 10, nullable = false)
    private String direction;

    @Column(name = "SEGMENT", length = 50)
    private String segment;

    @Column(name = "CREDITOR_AGENT", length = 11)
    private String creditorAgent;

    @Column(name = "CREDITOR_LRC", length = 35)
    private String creditorLrc;

    @Column(name = "DEBTOR_LRC", length = 35)
    private String debtorLrc;

    @Column(name = "DEBTOR_ACCOUNT_NO", length = 34)
    private String debtorAccountNo;

    @Column(name = "CR_STATISTICAL_CODE", length = 20)
    private String crStatisticalCode;

    @Column(name = "AMOUNT", precision = 18, scale = 2)
    private BigDecimal amount;

    @Column(name = "AMOUNT_RSD", precision = 18, scale = 2)
    private BigDecimal amountRsd;

    @Column(name = "MIDDRATE", precision = 15, scale = 8)
    private BigDecimal middrate;

    @Column(name = "SDC", precision = 2, scale = 0)
    private Integer sdc;

    @Column(name = "CREDIT_ACCOUNT", precision = 11, scale = 0)
    private Long creditAccount;

    @Column(name = "DEBIT_ACCOUNT", precision = 11, scale = 0)
    private Long debitAccount;

    @Column(name = "FEE", precision = 18, scale = 2)
    private BigDecimal fee;

    @Column(name = "APPLIED_FEE_RULE_NO")
    private Integer appliedFeeRuleNo;

    @Column(name = "BUDGET_CODE", length = 20)
    private String budgetCode;

    @Column(name = "TRANSACTION_CODE", length = 20)
    private String transactionCode;

    @Column(name = "CURRENCY", length = 10)
    private String currency;

    @Column(name = "NARRATIVE1", length = 35)
    private String narrative1;

    @Column(name = "NARRATIVE2", length = 35)
    private String narrative2;

    @Column(name = "OPU", length = 4)
    private String opu;

    @Column(name = "REPORTING_DATE", length = 30)
    private String reportingDate;

    @Column(name = "VALUE_DATE", length = 30)
    private String valueDate;

    @Column(name = "REF", length = 70)
    private String ref;

    @Column(name = "BOOKING_STATUS", length = 20, nullable = false)
    private String bookingStatus;

    @Column(name = "STATUS_UPDATED_AT", nullable = false)
    private LocalDateTime statusUpdatedAt;

    @Column(name = "UPDATED_BY", length = 100, nullable = false)
    private String updatedBy;

    @Column(name = "UPDATED_AT", nullable = false)
    private LocalDateTime updatedAt;

    @PrePersist
    public void prePersist() {
        if (bookingStatus == null || bookingStatus.isBlank()) {
            bookingStatus = "NEW";
        }
        if (statusUpdatedAt == null) {
            statusUpdatedAt = LocalDateTime.now();
        }
        if (updatedBy == null || updatedBy.isBlank()) {
            updatedBy = "system";
        }
        if (updatedAt == null) {
            updatedAt = LocalDateTime.now();
        }
    }
}

package rs.unicredit.cbr.service;

import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import rs.unicredit.cbr.config.GlFeePrepareDataProperties;
import rs.unicredit.cbr.dto.GlFeePrepareDataResponse;
import rs.unicredit.cbr.model.TransferDirection;

@Service
@ConditionalOnProperty(prefix = "customs.services.gl-fee-prepare-data", name = "enabled", havingValue = "true")
@ConditionalOnClass(name = "com.ibm.as400.access.AS400JDBCDriver")
public class GlFeePrepareDataService {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeePrepareDataService.class);
    private static final String FETCH_SQL_OUT = """
            SELECT f.*
            FROM TABLE(BEGPL.GET_FEEACCOUNT_OUT(CAST(? AS CHAR(16)))) f
            """;
    private static final String FETCH_SQL_IN = """
            SELECT f.*
            FROM TABLE(BEGPL.GET_FEEACCOUNT_IN(CAST(? AS CHAR(16)))) f
            """;

    private final JdbcTemplate jdbcTemplate;
    private final GlFeePrepareDataProperties properties;
    private final ObjectMapper objectMapper;

    public GlFeePrepareDataService(
            @Qualifier("glFeePrepareDataJdbcTemplate") JdbcTemplate jdbcTemplate,
            GlFeePrepareDataProperties properties,
            ObjectMapper objectMapper) {
        this.jdbcTemplate = jdbcTemplate;
        this.properties = properties;
        this.objectMapper = objectMapper;
    }

    public GlFeePrepareDataResponse fetchByInRef(String inRef) {
        return fetchByInRef(inRef, TransferDirection.OUT);
    }

    public GlFeePrepareDataResponse fetchByInRef(String inRef, TransferDirection direction) {
        if (!properties.isEnabled()) {
            throw new IllegalStateException("GL fee prepare data service is disabled");
        }
        String normalizedInRef = normalize(inRef);
        if (normalizedInRef == null) {
            throw new IllegalArgumentException("INREF is required");
        }
        if (normalizedInRef.length() > 16) {
            throw new IllegalArgumentException("INREF must have at most 16 characters: " + normalizedInRef);
        }
        TransferDirection resolvedDirection = resolveDirection(direction);
        String functionName = resolveFunctionName(resolvedDirection);
        String fetchSql = resolveFetchSql(resolvedDirection);
        long startedAt = System.currentTimeMillis();
        List<Map<String, Object>> rows;
        try {
            rows = jdbcTemplate.query(
                    connection -> {
                        PreparedStatement statement = connection.prepareStatement(fetchSql);
                        statement.setString(1, normalizedInRef);
                        statement.setQueryTimeout(Math.max(1, properties.getQueryTimeoutSeconds()));
                        return statement;
                    },
                    (ResultSet rs) -> {
                        List<Map<String, Object>> result = new ArrayList<>();
                        ResultSetMetaData metaData = rs.getMetaData();
                        int columnCount = metaData.getColumnCount();
                        while (rs.next()) {
                            Map<String, Object> row = new LinkedHashMap<>();
                            for (int index = 1; index <= columnCount; index++) {
                                row.put(metaData.getColumnLabel(index), rs.getObject(index));
                            }
                            result.add(row);
                        }
                        return result;
                    });
        } catch (DataAccessException ex) {
            SQLException sqlException = extractSqlException(ex);
            String sqlState = sqlException != null ? sqlException.getSQLState() : null;
            int errorCode = sqlException != null ? sqlException.getErrorCode() : 0;
            String message = sqlException != null && sqlException.getMessage() != null
                    ? sqlException.getMessage()
                    : ex.getMostSpecificCause() != null ? ex.getMostSpecificCause().getMessage() : ex.getMessage();
            LOG.error(
                    "AS400 {} failed inRef={} direction={} sqlState={} errorCode={} message={}",
                    functionName,
                    normalizedInRef,
                    resolvedDirection,
                    sqlState,
                    errorCode,
                    message,
                    ex);
            throw new ResponseStatusException(
                    HttpStatus.BAD_GATEWAY,
                    "AS400 %s failed for inRef=%s direction=%s sqlState=%s errorCode=%s message=%s"
                            .formatted(functionName, normalizedInRef, resolvedDirection, sqlState, errorCode, message));
        }
        long durationMs = System.currentTimeMillis() - startedAt;
        LOG.info(
                "AS400 {} success inRef={} direction={} rowCount={} durationMs={} rows={}",
                functionName,
                normalizedInRef,
                resolvedDirection,
                rows.size(),
                durationMs,
                toJson(rows));
        return GlFeePrepareDataResponse.builder()
                .inRef(normalizedInRef)
                .rowCount(rows.size())
                .durationMs(durationMs)
                .rows(rows)
                .build();
    }

    private TransferDirection resolveDirection(TransferDirection direction) {
        if (direction == null) {
            return TransferDirection.OUT;
        }
        return direction;
    }

    private String resolveFunctionName(TransferDirection direction) {
        return direction == TransferDirection.IN ? "GET_FEEACCOUNT_IN" : "GET_FEEACCOUNT_OUT";
    }

    private String resolveFetchSql(TransferDirection direction) {
        return direction == TransferDirection.IN ? FETCH_SQL_IN : FETCH_SQL_OUT;
    }

    private String toJson(List<Map<String, Object>> rows) {
        try {
            return objectMapper.writeValueAsString(rows);
        } catch (JsonProcessingException ex) {
            LOG.warn("Failed to serialize GET_FEEACCOUNT rows: {}", ex.getMessage());
            return String.valueOf(rows);
        }
    }

    private String normalize(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private SQLException extractSqlException(Throwable throwable) {
        if (throwable == null) {
            return null;
        }
