package rs.unicredit.cbr.service;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import rs.unicredit.cbr.config.GlFeeBookingPreparationProperties;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.GlFeeData;
import rs.unicredit.cbr.model.MessageType;
import rs.unicredit.cbr.model.TransferDirection;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@Service
@RequiredArgsConstructor
public class GlFeeDataService {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeDataService.class);
    private static final String TXN_FEE_STATUS_READY = "READY";
    private static final String TXN_FEE_STATUS_TAKEN = "TAKEN";
    private static final DateTimeFormatter GL_DATE_TIME_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'00:00:00");

    private final CbrTransactionRepository transactionRepository;
    private final GlFeeDataRepository glFeeDataRepository;
    private final GlFeeBookingPreparationProperties glFeeBookingPreparationProperties;
    private final GlFeeAuditActorService glFeeAuditActorService;

    @Transactional
    public int takeReadyTransactionsIntoFeeData() {
        return takeReadyTransactionsIntoFeeData(LocalDateTime.now());
    }

    @Transactional
    public int takeReadyTransactionsIntoFeeData(LocalDateTime cutoff) {
        List<CbrTransaction> candidates = transactionRepository
                .findAllByFeeStatusAndMessageTypeAndDirectionInAndFeeReadyAtLessThanEqualOrderByIdAsc(
                        TXN_FEE_STATUS_READY,
                        MessageType.P8,
                        List.of(TransferDirection.OUT, TransferDirection.INT, TransferDirection.IN),
                        cutoff);

        int takenCount = 0;
        for (CbrTransaction transaction : candidates) {
            if (transaction == null || transaction.getId() == null) {
                continue;
            }
            if (takeSingleTransaction(transaction)) {
                takenCount++;
            }
        }

        LOG.info("GL fee take completed cutoff={} candidates={} taken={}", cutoff, candidates.size(), takenCount);
        return takenCount;
    }

    private boolean takeSingleTransaction(CbrTransaction transaction) {
        if (!isProtectedCandidate(transaction)) {
            LOG.warn(
                    "Skipping GL fee take for txnId={} requestId={} because candidate protection failed feeStatus={} status={} messageType={} direction={}",
                    transaction.getId(),
                    transaction.getRequest() != null ? transaction.getRequest().getId() : null,
                    transaction.getFeeStatus(),
                    transaction.getStatus(),
                    transaction.getMessageType(),
                    transaction.getDirection());
            return false;
        }

        if (glFeeDataRepository.existsByCallReplyRef(transaction.getCallReplyRef())) {
            int updated = transactionRepository.updateFeeStatusById(transaction.getId(), TXN_FEE_STATUS_TAKEN);
            LOG.info(
                    "GL fee row already exists for txnId={} requestId={} callReplyRef={}, marking transaction as TAKEN updatedRows={}",
                    transaction.getId(),
                    transaction.getRequest().getId(),
                    transaction.getCallReplyRef(),
                    updated);
            return updated > 0;
        }

        String glDate = LocalDateTime.now().format(GL_DATE_TIME_FORMATTER);
        LocalDateTime now = LocalDateTime.now();
        GlFeeData saved = glFeeDataRepository.save(GlFeeData.builder()
                .requestId(transaction.getRequest().getId())
                .callReplyRef(transaction.getCallReplyRef())
                .messageType(transaction.getMessageType().name())
                .direction(transaction.getDirection().name())
                .segment(resolveSegment(transaction))
                .budgetCode(normalize(glFeeBookingPreparationProperties.getBudgetCode()))
                .transactionCode(normalize(glFeeBookingPreparationProperties.getTransactionCode()))
                .currency(normalize(glFeeBookingPreparationProperties.getCurrency()))
                .creditorAgent(transaction.getCreditorAgent())
                .creditorLrc(transaction.getCreditorLrc())
                .debtorLrc(transaction.getDebtorLrc())
                .debtorAccountNo(normalize(transaction.getDebtorAccountNo()))
                .crStatisticalCode(transaction.getCrStatisticalCode())
                .narrative2(transaction.getCallReplyRef())
                .reportingDate(glDate)
                .valueDate(glDate)
                .bookingStatus("NEW")
                .statusUpdatedAt(now)
                .updatedBy(glFeeAuditActorService.resolveActorOrSystem())
                .updatedAt(now)
                .build());

        int updated = transactionRepository.updateFeeStatusById(transaction.getId(), TXN_FEE_STATUS_TAKEN);
        LOG.info(
                "Inserted GL fee row id={} for txnId={} requestId={} callReplyRef={} and marked transaction feeStatus=TAKEN updatedRows={}",
                saved.getId(),
                transaction.getId(),
                transaction.getRequest().getId(),
                transaction.getCallReplyRef(),
                updated);
        return updated > 0;
    }

    private boolean isProtectedCandidate(CbrTransaction transaction) {
        if (transaction == null) {
            return false;
        }
        return TXN_FEE_STATUS_READY.equalsIgnoreCase(transaction.getFeeStatus())
                && GlFeeEligibility.isReadyCandidate(transaction);
    }

    private String resolveSegment(CbrTransaction transaction) {
        return GlFeeEligibility.resolveSegment(transaction);
    }

    private String normalize(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
}

