import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Lob;
import jakarta.persistence.PrePersist;
import jakarta.persistence.PreUpdate;
import jakarta.persistence.SequenceGenerator;
import jakarta.persistence.Table;

import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;

@Entity
@Table(name = "TBL_CBR_TRANSACTION_REQUEST")
@NoArgsConstructor
@AllArgsConstructor
@Getter
@Setter
@ToString
public class CbrTransactionRequest implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @GeneratedValue(generator = "cbrTransactionRequestSeq", strategy = GenerationType.SEQUENCE)
    @SequenceGenerator(name = "cbrTransactionRequestSeq", sequenceName = "TBL_CBR_TRANSACTION_REQUEST_SEQ", allocationSize = 1)
    private Long id;

    @Column(name = "SOURCE_SYSTEM", length = 20)
    private String sourceSystem;

    @Column(name = "RECEIVED_AT")
    private LocalDateTime receivedAt;

    @Basic(fetch = FetchType.LAZY)
    @Lob
    @Column(name = "RAW_XML", columnDefinition = "CLOB", nullable = false)
    private String rawXml;

    @Column(name = "STATUS", length = 20)
    private String status;

    @Column(name = "ERROR_MESSAGE", length = 1024)
    private String errorMessage;

    @Column(name = "CORRELATION_ID", length = 100)
    private String correlationId;

    @Column(name = "CORRELATION_ID_SOURCE", length = 20)
    private String correlationIdSource;

    @PrePersist
    public void prePersist() {
        receivedAt = receivedAt == null ? LocalDateTime.now() : receivedAt;
        status = status == null ? "S1" : status;
        normalizePersistedFields();
    }

    @PreUpdate
    public void preUpdate() {
        normalizePersistedFields();
    }

    private void normalizePersistedFields() {
        errorMessage = truncate(errorMessage, 1024);
    }

    private String truncate(String value, int maxLength) {
        if (value == null || value.length() <= maxLength) {
            return value;
        }
        return value.substring(0, maxLength);
    }
}

