@Component
@RequiredArgsConstructor
@ConditionalOnProperty(prefix = "customs.fee-booking.execute-prepared", name = "enabled", havingValue = "true")
public class GlFeeBookingExecutionScheduler {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeBookingExecutionScheduler.class);

    private final GlFeeBookingExecutionService glFeeBookingExecutionService;
    private final AtomicBoolean running = new AtomicBoolean(false);

    @Scheduled(fixedDelayString = "${customs.fee-booking.execute-prepared.fixed-delay-ms:60000}")
    public void executePreparedFeeRows() {
        if (!running.compareAndSet(false, true)) {
            LOG.info("Skipping GL fee booking scheduler because previous run is still in progress.");
            return;
        }
        try {
            int booked = glFeeBookingExecutionService.executePreparedRows();
            LOG.info("GL fee booking scheduler finished booked={}", booked);
        } catch (Exception ex) {
            LOG.error("GL fee booking scheduler failed: {}", ex.getMessage(), ex);
        } finally {
            running.set(false);
        }
    }
}

