package rs.unicredit.cbr.service;

import java.math.BigInteger;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

import com.fasterxml.jackson.databind.JsonNode;

@Service
public class ContractStatusService {

    private static final Logger LOG = LoggerFactory.getLogger(ContractStatusService.class);

    private final RestTemplate restTemplate;

    @Value("${customs.services.contract-status.base-url:}")
    private String baseUrl;

    @Value("${customs.services.contract-status.user-id:AUTO}")
    private String userId;

    @Value("${customs.services.contract-status.opu:HEOF}")
    private String opu;

    @Value("${customs.services.contract-status.source-app:CBR}")
    private String sourceApp;

    @Value("${customs.services.contract-status.retry.max-attempts:3}")
    private int maxAttempts;

    @Value("${customs.services.contract-status.retry.backoff-ms:500}")
    private long backoffMs;

    public ContractStatusService(@Qualifier("contractStatusRestTemplate") RestTemplate restTemplate) {
        this.restTemplate = restTemplate;
    }

    public String fetchContractByAccount(String account) {
        String clientId = deriveClientId(account);
        if (clientId == null) {
            return null;
        }
        return fetchContractByClientId(clientId);
    }

    public String fetchContractByClientId(String clientId) {
        if (isBlank(baseUrl)) {
            LOG.info("Contract-status call skipped: base-url not configured");
            return null;
        }
        if (!isValidClientId(clientId)) {
            LOG.warn("Contract-status call skipped: invalid clientId='{}' (expected 8 chars)", clientId);
            return null;
        }

        Map<String, Object> payload = new LinkedHashMap<>();
        Map<String, String> requestHeader = new LinkedHashMap<>();
        requestHeader.put("userId", userId);
        requestHeader.put("opu", opu);
        requestHeader.put("sourceApp", sourceApp);
        requestHeader.put("requestCode", UUID.randomUUID().toString());
        payload.put("requestHeader", requestHeader);
        payload.put("clientId", clientId);

        for (int attempt = 1; attempt <= Math.max(1, maxAttempts); attempt++) {
            try {
                ResponseEntity<JsonNode> response = restTemplate.postForEntity(baseUrl, payload, JsonNode.class);
                JsonNode body = response.getBody();
                String returnCode = text(body, "responseHeader", "returnCode");
                if ("N".equalsIgnoreCase(returnCode)) {
                    JsonNode errors = body != null ? body.get("errors") : null;
                    LOG.warn("Contract-status business error for clientId={} returnCode=N errors={}",
                            clientId, errors);
                    return null;
                }
                if (!"Y".equalsIgnoreCase(returnCode)) {
                    String returnMessage = text(body, "responseHeader", "returnMessage");
                    LOG.warn("Contract-status unexpected returnCode='{}' returnMessage='{}' for clientId={}",
                            returnCode, returnMessage, clientId);
                    return null;
                }
                String contract = text(body, "contract");
                if (isBlank(contract)) {
                    LOG.warn("Contract-status response missing contract for clientId={}", clientId);
                    return null;
                }
                return contract.trim();
            } catch (HttpServerErrorException | ResourceAccessException ex) {
                if (attempt < Math.max(1, maxAttempts)) {
                    long sleepMs = Math.max(0L, backoffMs) * attempt;
                    LOG.warn("Contract-status transient failure attempt {}/{} for clientId={}, retry in {}ms: {}",
                            attempt, maxAttempts, clientId, sleepMs, ex.getMessage());
                    sleepQuietly(sleepMs);
                    continue;
                }
                LOG.error("Contract-status failed after {} attempts for clientId={}: {}",
                        maxAttempts, clientId, ex.getMessage());
                return null;
            } catch (RestClientException ex) {
                LOG.error("Contract-status HTTP/client error for clientId={}: {}", clientId, ex.getMessage());
                return null;
            }
        }
        return null;
    }

    public Map<String, Object> probe(String clientId, String account) {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("service", "CONTRACT_STATUS");
        result.put("baseUrl", baseUrl);
        result.put("account", normalize(account));
        result.put("clientId", normalize(clientId));

        if (isBlank(baseUrl)) {
            result.put("ok", false);
            result.put("error", "Base URL is not configured");
            return result;
        }

        String resolvedClientId = !isBlank(clientId) ? clientId.trim() : deriveClientId(account);
        result.put("resolvedClientId", resolvedClientId);
        if (!isValidClientId(resolvedClientId)) {
            result.put("ok", false);
            result.put("error", "Valid clientId is required or account must resolve to 8-digit clientId");
            return result;
        }

        String contract = fetchContractByClientId(resolvedClientId);
        result.put("ok", !isBlank(contract));
        result.put("contract", contract);
        if (isBlank(contract)) {
            result.put("error", "No contract returned or service call failed");
        }
        return result;
    }

    private String deriveClientId(String account) {
        if (isBlank(account)) {
            LOG.info("Contract-status call skipped: account is blank");
            return null;
        }
        String digits = account.replaceAll("\\D", "");
        if (isBlank(digits)) {
            LOG.warn("Contract-status call skipped: no digits in account='{}'", account);
            return null;
        }
        try {
            BigInteger raw = new BigInteger(digits);
            BigInteger divided = raw.divide(BigInteger.valueOf(1000));
            String normalized = divided.toString();
            if (normalized.length() > 8) {
                LOG.warn("Contract-status call skipped: derived clientId too long '{}' from account='{}'",
                        normalized, account);
                return null;
            }
            return String.format("%8s", normalized).replace(' ', '0');
        } catch (Exception ex) {
            LOG.warn("Contract-status call skipped: failed to derive clientId from account='{}': {}",
                    account, ex.getMessage());
            return null;
        }
    }

    private boolean isValidClientId(String clientId) {
        return !isBlank(clientId) && clientId.matches("\\d{8}");
    }

    private String text(JsonNode node, String... path) {
        if (node == null || path == null || path.length == 0) {
            return null;
        }
        JsonNode resolved = node;
        for (String segment : path) {
            if (segment == null) {
                return null;
            }
            resolved = resolved.path(segment);
        }
        if (resolved == null || resolved.isMissingNode() || resolved.isNull()) {
            return null;
        }
        String value = resolved.asText(null);
        return isBlank(value) ? null : value.trim();
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private String normalize(String value) {
        return isBlank(value) ? null : value.trim();
    }

    private void sleepQuietly(long millis) {
        if (millis <= 0) {
            return;
        }
        try {
            Thread.sleep(millis);
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
        }
    }
}

