    private boolean matchesCreditorLrcPrefix(CbrTransaction txn) {
        if (txn == null || isBlank(txn.getCreditorLrc())) {
            return false;
        }
        String normalized = txn.getCreditorLrc().trim();
        return normalized.startsWith("509") || normalized.startsWith("538");
    }

    private boolean isManualProcessingRequired(CbrTransaction txn) {
        return !evaluateStpManualFailures(txn).isEmpty();
    }

    private List<String> evaluateStpManualFailures(CbrTransaction txn) {
        if (txn != null) {
            LOG.info("STP input txnId={} requestId={} messageType={} direction={} reportType='{}'",
                    txn.getId(),
                    txn.getRequest() != null ? txn.getRequest().getId() : null,
                    txn.getMessageType(),
                    txn.getDirection(),
                    txn.getReportType());
        }
        // Business override: all transactions with report type 66 pass STP checks.
        if (txn != null && "66".equals(normalize(txn.getReportType()))) {
            LOG.info("STP override applied for txnId={} reportType={}", txn.getId(), txn.getReportType());
            return List.of();
        }
        if (txn == null || txn.getMessageType() != MessageType.P8) {
            return List.of();
        }
        TransferDirection direction = txn.getDirection();
        if (direction == TransferDirection.OUT || direction == TransferDirection.INT) {
