    @Test
    void hasBlockingPostMatrixValidationFailureRecognizesFailuresFromOneToSixteen() {
        List<ValidationApplyResult> results = List.of(
                ValidationApplyResult.builder()
                        .validationNo(new BigDecimal("16"))
                        .failedConditions(List.of("bad"))
                        .build(),
                ValidationApplyResult.builder()
                        .validationNo(new BigDecimal("66.4"))
                        .failedConditions(List.of("matrix"))
                        .build());

        assertThat(service.hasBlockingPostMatrixValidationFailure(results)).isTrue();
    }

    @Test
    void isManualProcessingRequiredByRequestIdReturnsEmptyWhenTransactionMissing() {
        when(transactionRepository.findWithRegulatoryDetailsByRequestId(100L)).thenReturn(Optional.empty());

        assertThat(service.isManualProcessingRequiredByRequestId(100L)).isEmpty();
        verify(stpValidationLogRepository, never()).save(any());
    }

    @Test
    void isManualProcessingRequiredByRequestIdReturnsManualForInvalidPaymentInstrument() throws Exception {
        CbrTransactionRequest request = new CbrTransactionRequest();
        request.setId(200L);
        CbrTransactionStat stat = new CbrTransactionStat();
        stat.setSplitStatCode("112");
        CbrTransaction txn = CbrTransaction.builder()
                .id(1L)
                .request(request)
                .messageType(MessageType.P8)
                .direction(TransferDirection.IN)
                .paymentInstrument("9")
                .specialMark("1")
                .debtorCountry("XK")
                .customerId("12345678")
                .regulatoryDetails(List.of(stat))
                .build();
        when(transactionRepository.findWithRegulatoryDetailsByRequestId(200L)).thenReturn(Optional.of(txn));
        when(transactionRepository.findFirstByRequestId(200L)).thenReturn(txn);
        when(requestRepository.findById(200L)).thenReturn(Optional.of(request));
        when(stpValidationLogRepository.findMaxRunNoByRequestId(200L)).thenReturn(null);
        when(stpValidationLogRepository.save(any())).thenAnswer(invocation -> invocation.getArgument(0));

        Optional<StpManualCheckResponse> response = service.isManualProcessingRequiredByRequestId(200L);

        assertThat(response).isPresent();
        assertThat(response.get().isManualRequired()).isTrue();
        assertThat(response.get().getFailures()).extracting("code").contains("PAYMENT_INSTRUMENT");
        verify(transactionRepository).updateCustomerStpByRequestId(200L, "NE");
        verify(stageTransitionService).transitionByRequestId(200L, "S7", "STP status update");
        verify(stpValidationLogRepository).save(argThat(logEntry ->
                logEntry instanceof CbrStpValidationLog stpLog
                        && Long.valueOf(1L).equals(stpLog.getRunNo())));
    }

