package rs.unicredit.cbr.service;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.MessageType;
import rs.unicredit.cbr.model.TransferDirection;

class GlFeeEligibilityTest {

    @Test
    void readyCandidateReturnsTrueForOutgoingP8RegardlessOfSegment() {
        CbrTransaction transaction = transaction(MessageType.P8, TransferDirection.OUT, null, null);

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isTrue();
    }

    @Test
    void readyCandidateReturnsTrueForInternalP8WhenDebtorSegmentIsPi() {
        CbrTransaction transaction = transaction(MessageType.P8, TransferDirection.INT, "PI", null);

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isTrue();
    }

    @Test
    void readyCandidateReturnsTrueForInternalP8WhenCreditorSegmentIsPiAndDebtorMissing() {
        CbrTransaction transaction = transaction(MessageType.P8, TransferDirection.INT, null, "PI");

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isTrue();
    }

    @Test
    void readyCandidateReturnsFalseForInternalP8WhenResolvedSegmentIsNotPi() {
        CbrTransaction transaction = transaction(MessageType.P8, TransferDirection.INT, "CO", null);

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isFalse();
    }

    @Test
    void readyCandidateReturnsTrueForIncomingP8WhenDebtorSegmentIsPi() {
        CbrTransaction transaction = transaction(MessageType.P8, TransferDirection.IN, "PI", null);

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isTrue();
    }

    @Test
    void readyCandidateReturnsTrueForIncomingP8WhenCreditorSegmentIsPiAndDebtorMissing() {
        CbrTransaction transaction = transaction(MessageType.P8, TransferDirection.IN, null, "PI");

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isTrue();
    }

    @Test
    void readyCandidateReturnsFalseForIncomingP8WhenResolvedSegmentIsNotPi() {
        CbrTransaction transaction = transaction(MessageType.P8, TransferDirection.IN, "CO", null);

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isFalse();
    }

    @Test
    void readyCandidateReturnsFalseForNonP8Messages() {
        CbrTransaction transaction = transaction(MessageType.P4, TransferDirection.OUT, "PI", null);

        assertThat(GlFeeEligibility.isReadyCandidate(transaction)).isFalse();
    }

    @Test
    void resolveSegmentPrefersDebtorSegment() {
        assertThat(GlFeeEligibility.resolveSegment("PI", "CO")).isEqualTo("PI");
    }

    private CbrTransaction transaction(
            MessageType messageType,
            TransferDirection direction,
            String debtorSegment,
            String creditorSegment) {
        CbrTransaction transaction = new CbrTransaction();
        transaction.setMessageType(messageType);
        transaction.setDirection(direction);
        transaction.setDebtorSegment(debtorSegment);
        transaction.setCreditorSegment(creditorSegment);
        return transaction;
    }
}

