package rs.unicredit.cbr.service;

import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.MessageType;
import rs.unicredit.cbr.model.TransferDirection;

public final class GlFeeEligibility {

    private static final String SEGMENT_PI = "PI";
    private static final String OUT_EXCLUDED_SEGMENT_SME_LEGAL_ENTITY = "SME pravno lice-Retail";
    private static final String OUT_EXCLUDED_DEBTOR_LRC = "504306";

    private GlFeeEligibility() {
    }

    public static boolean isReadyCandidate(CbrTransaction transaction) {
        if (transaction == null) {
            return false;
        }

        return isReadyCandidate(
                transaction.getMessageType(),
                transaction.getDirection(),
                transaction.getDebtorSegment(),
                transaction.getCreditorSegment(),
                transaction.getDebtorLrc());
    }

    public static boolean isReadyCandidate(
            MessageType messageType,
            TransferDirection direction,
            String debtorSegment,
            String creditorSegment) {
        return isReadyCandidate(messageType, direction, debtorSegment, creditorSegment, null);
    }

    public static boolean isReadyCandidate(
            MessageType messageType,
            TransferDirection direction,
            String debtorSegment,
            String creditorSegment,
            String debtorLrc) {
        if (messageType != MessageType.P8) {
            return false;
        }

        if (direction == TransferDirection.OUT) {
            return !isExcludedOutgoingCandidate(resolveSegment(debtorSegment, creditorSegment), debtorLrc);
        }

        if (direction != TransferDirection.INT && direction != TransferDirection.IN) {
            return false;
        }

        return SEGMENT_PI.equalsIgnoreCase(resolveSegment(debtorSegment, creditorSegment));
    }

    public static String resolveSegment(CbrTransaction transaction) {
        if (transaction == null) {
            return null;
        }

        return resolveSegment(transaction.getDebtorSegment(), transaction.getCreditorSegment());
    }

    static String resolveSegment(String debtorSegment, String creditorSegment) {
        String normalizedDebtorSegment = normalize(debtorSegment);
        if (normalizedDebtorSegment != null) {
            return normalizedDebtorSegment;
        }

        return normalize(creditorSegment);
    }

    private static boolean isExcludedOutgoingCandidate(String segment, String debtorLrc) {
        return OUT_EXCLUDED_SEGMENT_SME_LEGAL_ENTITY.equalsIgnoreCase(normalize(segment))
                && OUT_EXCLUDED_DEBTOR_LRC.equalsIgnoreCase(normalize(debtorLrc));
    }

    private static String normalize(String value) {
        if (value == null) {
            return null;
        }

        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
}
